create table if not exists public.private_market_ingestion_runs(id uuid primary key default gen_random_uuid(),source_file text not null,file_sha256 text not null,dataset_domain text not null check(dataset_domain in('india_deal_market','global_opportunity_intelligence','global_investor_network')),effective_date date,status text not null default 'processing',records_seen integer not null default 0,records_accepted integer not null default 0,records_rejected integer not null default 0,errors jsonb not null default '[]',created_at timestamptz not null default now(),unique(file_sha256,dataset_domain));
create table if not exists public.private_market_sources(id uuid primary key default gen_random_uuid(),ingestion_run_id uuid not null references public.private_market_ingestion_runs(id) on delete cascade,source_file text not null,source_sheet text not null,source_row integer not null,effective_date date,original_values jsonb not null default '{}',normalized_values jsonb not null default '{}',unique(ingestion_run_id,source_sheet,source_row));
create table if not exists public.private_market_companies(id uuid primary key default gen_random_uuid(),canonical_name text not null,normalized_name text not null,description text,city text,state text,country text,geography_scope text not null default 'global',entity_match_confidence numeric check(entity_match_confidence between 0 and 1),unique(normalized_name,country));
create table if not exists public.private_market_deals(id uuid primary key default gen_random_uuid(),company_id uuid references public.private_market_companies(id),company_name text not null,deal_date date,deal_size_inr_mn numeric,stake_percent numeric,pre_money_valuation_inr_mn numeric,post_money_valuation_inr_mn numeric,business_description text,location text,transaction_type text not null,transaction_subcategory text,deal_type text,market_domain text not null check(market_domain in('core','public')),source_id uuid not null references public.private_market_sources(id),ingestion_run_id uuid not null references public.private_market_ingestion_runs(id),source_file text not null,source_sheet text not null,source_row integer not null,effective_date date,is_public boolean not null default true,unique(ingestion_run_id,source_sheet,source_row));
create table if not exists public.private_market_investors(id uuid primary key default gen_random_uuid(),name text not null,normalized_name text not null unique,headquarters text,source_id uuid references public.private_market_sources(id),is_public boolean not null default true);
create table if not exists public.private_market_investor_transactions(id uuid primary key default gen_random_uuid(),investor_id uuid not null references public.private_market_investors(id) on delete cascade,company_name text not null,observed_date date,transaction_description text,source_id uuid not null references public.private_market_sources(id));
create table if not exists public.private_market_opportunities(id uuid primary key default gen_random_uuid(),company_id uuid references public.private_market_companies(id),company_name text not null,opportunity_type text not null check(opportunity_type in('sale_divestment','lbo','distressed')),geography_scope text not null default 'global',observed_metrics jsonb not null default '{}',screen_rules jsonb not null default '{}',coverage numeric,source_id uuid not null references public.private_market_sources(id),ingestion_run_id uuid not null references public.private_market_ingestion_runs(id),is_public boolean not null default true,unique(ingestion_run_id,source_id,opportunity_type));
create table if not exists public.private_market_entity_review(id uuid primary key default gen_random_uuid(),ingestion_run_id uuid not null references public.private_market_ingestion_runs(id),source_id uuid not null references public.private_market_sources(id),proposed_company_id uuid references public.private_market_companies(id),source_name text not null,confidence numeric not null,status text not null default 'pending');
create index if not exists private_market_deals_scope_date_idx on public.private_market_deals(market_domain,deal_date desc);
create index if not exists private_market_opportunities_type_idx on public.private_market_opportunities(opportunity_type,geography_scope);
alter table public.private_market_ingestion_runs enable row level security;
alter table public.private_market_sources enable row level security;
alter table public.private_market_companies enable row level security;
alter table public.private_market_deals enable row level security;
alter table public.private_market_investors enable row level security;
alter table public.private_market_investor_transactions enable row level security;
alter table public.private_market_opportunities enable row level security;
alter table public.private_market_entity_review enable row level security;
comment on table public.private_market_deals is 'India Deal Market evidence with public activity separated from core private markets.';
comment on table public.private_market_opportunities is 'Global opportunity universe, never aggregated into India Deal Market metrics.';
